cat > ~/parse-practice.js << 'EOF'
// Parse: string → object
const raw = '{"species":"Rainbow Trout","length":18,"released":true}';
const catch1 = JSON.parse(raw);

console.log(catch1.species);     // 'Rainbow Trout'
console.log(catch1.length);      // 18
console.log(typeof catch1);      // 'object'

// Stringify: object → string
const asString = JSON.stringify(catch1);
console.log(asString);           // compact
console.log(typeof asString);    // 'string'

// Pretty-print for logging
const pretty = JSON.stringify(catch1, null, 2);
console.log(pretty);

// Read the JSON file you just created
import { readFileSync } from 'fs';
const fileContents = readFileSync(process.env.HOME + '/catch.json', 'utf8');
const logEntry = JSON.parse(fileContents);
console.log('Catches today:', logEntry.catches.length);
console.log('First species:', logEntry.catches[0].species);
EOF

node --input-type=module < ~/parse-practice.js
